	//clear data:
	f->id |= 0x80000000u;
	f->boundary = false;

	//clear connectivity:
	f->halfedge = halfedges.end();

	//move to free list:
	free_faces.splice(free_faces.end(), faces, f);
}

void Halfedge_Mesh::erase_halfedge(HalfedgeRef h) {
	//clear data:
	h->id |= 0x80000000u;
	h->corner_uv = Vec2(std::numeric_limits< float >::quiet_NaN(), std::numeric_limits< float >::quiet_NaN());
